-- One statement reads a consistent complete fact graph; this query never writes or exposes raw reference bodies.
WITH representations AS MATERIALIZED (__REPRESENTATION_SCOPE__),
outputs AS MATERIALIZED (SELECT o.* FROM romd."RepresentationOutputs" o WHERE o."RepresentationId" IN (SELECT "Id" FROM representations))
SELECT jsonb_build_object(
    'schemaVersion',(SELECT version FROM romd.romd_schema WHERE singleton),
    'logicalRoms',COALESCE((SELECT jsonb_agg(to_jsonb(a) ORDER BY a."Id") FROM romd."Roms" a WHERE a."Id" IN (SELECT "RomId" FROM outputs)),'[]'::jsonb),
    'files',COALESCE((SELECT jsonb_agg(jsonb_build_object('Id',a."Id",'Sha256',a."Sha256",'Size',a."Size",'SizeOnDisk',a."SizeOnDisk",'IsCompressed',a."IsCompressed") ORDER BY a."Id") FROM romd."Files" a WHERE a."Id" IN (SELECT "FileId" FROM representations UNION SELECT "StoredFileId" FROM romd."ReconstructionMembers" WHERE "RepresentationId" IN (SELECT "Id" FROM representations) AND "StoredFileId" IS NOT NULL)),'[]'::jsonb),
    'representations',COALESCE((SELECT jsonb_agg(to_jsonb(a) ORDER BY a."Id") FROM representations a),'[]'::jsonb),
    'outputs',COALESCE((SELECT jsonb_agg(to_jsonb(a) ORDER BY a."Id") FROM outputs a),'[]'::jsonb),
    'manifests',COALESCE((SELECT jsonb_agg(to_jsonb(a) ORDER BY a."RepresentationId") FROM romd."ReconstructionManifests" a WHERE a."RepresentationId" IN (SELECT "Id" FROM representations)),'[]'::jsonb),
    'tracks',COALESCE((SELECT jsonb_agg(to_jsonb(a) ORDER BY a."RepresentationId",a."Number") FROM romd."ReconstructionTracks" a WHERE a."RepresentationId" IN (SELECT "Id" FROM representations)),'[]'::jsonb),
    'members',COALESCE((SELECT jsonb_agg(to_jsonb(a) ORDER BY a."RepresentationId",a."Ordinal") FROM romd."ReconstructionMembers" a WHERE a."RepresentationId" IN (SELECT "Id" FROM representations)),'[]'::jsonb),
    'memberTracks',COALESCE((SELECT jsonb_agg(to_jsonb(a) ORDER BY a."RepresentationId",a."TrackNumber") FROM romd."ReconstructionMemberTracks" a WHERE a."RepresentationId" IN (SELECT "Id" FROM representations)),'[]'::jsonb),
    'chdParameters',COALESCE((SELECT jsonb_agg(to_jsonb(a) ORDER BY a."RepresentationId") FROM romd."ChdContainerParameters" a WHERE a."RepresentationId" IN (SELECT "Id" FROM representations)),'[]'::jsonb),
    'rvzParameters',COALESCE((SELECT jsonb_agg(to_jsonb(a) ORDER BY a."RepresentationId") FROM romd."RvzContainerParameters" a WHERE a."RepresentationId" IN (SELECT "Id" FROM representations)),'[]'::jsonb),
    'chdMetadata',COALESCE((SELECT jsonb_agg(to_jsonb(a) ORDER BY a."RepresentationId",a."Ordinal") FROM romd."ChdMetadataEntries" a WHERE a."RepresentationId" IN (SELECT "Id" FROM representations)),'[]'::jsonb),
    'verifications',COALESCE((SELECT jsonb_agg(to_jsonb(a) ORDER BY a."Id") FROM romd."Verifications" a WHERE a."RepresentationId" IN (SELECT "Id" FROM representations)),'[]'::jsonb),
    'verificationOutputs',COALESCE((SELECT jsonb_agg(to_jsonb(a) ORDER BY a."VerificationId",a."OutputId") FROM romd."VerificationOutputs" a WHERE a."RepresentationId" IN (SELECT "Id" FROM representations)),'[]'::jsonb),
    'creations',COALESCE((SELECT jsonb_agg(to_jsonb(a) ORDER BY a."Id") FROM romd."RepresentationCreations" a WHERE a."RepresentationId" IN (SELECT "Id" FROM representations)),'[]'::jsonb),
    'creationSources',COALESCE((SELECT jsonb_agg(to_jsonb(a) ORDER BY a."CreationId",a."TargetOutputId") FROM romd."CreationSources" a WHERE a."CreationId" IN (SELECT "Id" FROM romd."RepresentationCreations" WHERE "RepresentationId" IN (SELECT "Id" FROM representations))),'[]'::jsonb),
    'logicalInspections',COALESCE((SELECT jsonb_agg(to_jsonb(a) ORDER BY a."Id") FROM romd."LogicalInspections" a WHERE a."RomId" IN (SELECT "RomId" FROM outputs)),'[]'::jsonb),
    'ps2BootObservations',COALESCE((SELECT jsonb_agg(to_jsonb(a) ORDER BY a."InspectionId") FROM romd."Ps2BootObservations" a WHERE a."InspectionId" IN (SELECT "Id" FROM romd."LogicalInspections" WHERE "RomId" IN (SELECT "RomId" FROM outputs))),'[]'::jsonb),
    'cdBootInspections',COALESCE((SELECT jsonb_agg(to_jsonb(a) ORDER BY a."Id") FROM romd."CdBootInspections" a WHERE a."RepresentationId" IN (SELECT "Id" FROM representations)),'[]'::jsonb),
    'cdEncodingObservations',COALESCE((SELECT jsonb_agg(to_jsonb(a) ORDER BY a."CreationId") FROM romd."CdEncodingObservations" a WHERE a."RepresentationId" IN (SELECT "Id" FROM representations)),'[]'::jsonb),
    'archiveOwners',COALESCE((SELECT jsonb_agg(to_jsonb(a) ORDER BY a."LayoutId") FROM romd."CdArchiveOwners" a WHERE a."RepresentationId" IN (SELECT "Id" FROM representations)),'[]'::jsonb),
    'encodingAttempts',COALESCE((SELECT jsonb_agg(to_jsonb(a) ORDER BY a."JobId",a."Number") FROM romd."MediaReconciliationAttempts" a WHERE a."ResultRepresentationId" IN (SELECT "Id" FROM representations) AND a."Operation" = 'Encode' AND a."Outcome" = 'Recorded'),'[]'::jsonb),
    'verificationAttempts',COALESCE((SELECT jsonb_agg(to_jsonb(a) ORDER BY a."JobId",a."Number") FROM romd."MediaReconciliationAttempts" a WHERE a."ResultRepresentationId" IN (SELECT "Id" FROM representations) AND a."Operation" = 'Verify' AND a."Outcome" = 'Recorded'),'[]'::jsonb),
    'selectionItems',COALESCE((SELECT jsonb_agg(to_jsonb(i) ORDER BY i."SelectionJobId",i."Ordinal") FROM romd."MediaReconciliationSelectionItems" i WHERE i."SubjectKind" = 'Representation' AND i."SubjectId" IN (SELECT "Id" FROM representations)),'[]'::jsonb),
    'sourcePins',(SELECT count(*) FROM romd."MediaReconciliationPins"),
    'pendingDemand',(SELECT count(*) FROM romd."MediaReconciliationSubjects" WHERE "RequestedVersion" > "AcknowledgedVersion"))
